    // Check if we can handle at least minimal traffic
    if relayProcess.IsRunning() {
        w.WriteHeader(http.StatusOK)
        w.Write([]byte("ok"))
        return
    }
    http.Error(w, "relay process not running", http.StatusServiceUnavailable)
}
```

